import{_ as s,o as a,c as i,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Missing-Observations.md","filePath":"manual-en/Missing-Observations.md","lastUpdated":1785684581000}'),t={name:"manual-en/Missing-Observations.md"};function o(r,e,l,u,d,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h3 id="_6-6-handling-missing-observations" tabindex="-1">6.6 Handling missing observations <a class="header-anchor" href="#_6-6-handling-missing-observations" aria-label="Permalink to &quot;6.6 Handling missing observations&quot;">​</a></h3><p>PSPP includes special support for unknown numeric data values. Missing observations are assigned a special value, called the <em>system-missing value</em>. This “value” actually indicates the absence of a value; it means that the actual value is unknown. Procedures automatically exclude from analyses those observations or cases that have missing values. Details of missing value exclusion depend on the procedure and can often be controlled by the user; refer to descriptions of individual procedures for details.</p><p>The system-missing value exists only for numeric variables. String variables always have a defined value, even if it is only a string of spaces.</p><p>Variables, whether numeric or string, can have designated <em>user-missing values</em>. Every user-missing value is an actual value for that variable. However, most of the time user-missing values are treated in the same way as the system-missing value.</p><p>For more information on missing values, see the following sections: <a href="./Datasets">Datasets</a>, <a href="./MISSING-VALUES">MISSING VALUES</a>, <a href="./Expressions">Expressions</a>. See also the documentation on individual procedures for information on how they handle missing values.</p>',5)])])}const h=s(t,[["render",o]]);export{v as __pageData,h as default};
